output.raw:
{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "A"
      ],
      "content": "Hey, I'm working on producing squares since that's my specialty. I'm thinking we could trade some squares for circles if you're open to it. What do you think?"
    }
  },
  "rationale": "I have a specialty shape (square) that others need, so initiating a low-pressure trade discussion with A makes sense to build cooperation and get access to the circle I need for my order."
}

{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "B"
      ],
      "content": "Hey, I'm working on getting a square for my order. You have the specialty square, right? Maybe we can trade? I can produce a triangle if you're interested in buying one."
    }
  },
  "rationale": "I need a square to fulfill my order, and B has the specialty square. Starting a direct conversation to explore a trade makes sense since I can offer my triangle as a trade-in."
}

{
  "action": {
    "type": "message",
    "payload": {
      "channel": "direct",
      "recipients": [
        "C"
      ],
      "content": "Hey, I noticed you're the one who makes triangles. Since I need a triangle to fulfill my order, maybe we can trade? I can produce circles if you're open to it."
    }
  },
  "rationale": "I need a triangle to complete my order, and C is the only one who can produce it. Starting a direct conversation to propose a trade makes sense and aligns with my goal of fulfilling my order efficiently."
}

